func setAt(node interface{}, tokens []pathToken, value interface{}) (interface{}, bool) {
    if len(tokens) == 0 {
        return value, true
    }
    tok := tokens[0]
    if tok.isIndex {
        // node must be []interface{}
        slice, ok := node.([]interface{})
        if !ok {
            if node == nil {
                slice = nil
            } else {
                return node, false
            }
        }
        // grow
        if tok.index < 0 { return node, false }
        for len(slice) <= tok.index {
            slice = append(slice, nil)
        }
        child, ok := setAt(slice[tok.index], tokens[1:], value)
        if !ok { return node, false }
        slice[tok.index] = child
        return slice, true
    }
    // key token
    mp, ok := node.(map[string]interface{})
    if !ok {
        if node == nil {
            mp = map[string]interface{}{}
        } else {
            return node, false
        }
    }
    child, ok := setAt(mp[tok.key], tokens[1:], value)
    if !ok { return node, false }
    mp[tok.key] = child
    return mp, true
}
