func parsePath(path string) ([]pathToken, bool) {
    if path == "" { return nil, false }
    var tokens []pathToken
    parts := strings.Split(path, ".")
    for _, part := range parts {
        if part == "" { return nil, false }
        // extract key before first '['
        key := part
        rest := ""
        if i := strings.IndexByte(part, '['); i >= 0 {
            key = part[:i]
            rest = part[i:]
        }
        if key != "" {
            tokens = append(tokens, pathToken{key: key})
        } else if len(tokens) == 0 {
            return nil, false
        }
        // parse bracket indices
        for rest != "" {
            if rest[0] != '[' { return nil, false }
            end := strings.IndexByte(rest, ']')
            if end < 0 { return nil, false }
            numStr := rest[1:end]
            idx, err := strconv.Atoi(numStr)
            if err != nil || idx < 0 { return nil, false }
            tokens = append(tokens, pathToken{index: idx, isIndex: true})
            rest = rest[end+1:]
        }
    }
    return tokens, true
}
