```go
func deleteAt(node interface{}, tokens []pathToken) (interface{}, bool) {
	if len(tokens) == 0 { return node, false }
	tok := tokens[0]
	if len(tokens) == 1 {
		if tok.isIndex {
			slice, ok := node.([]interface{})
			if !ok || tok.index < 0 || tok.index >= len(slice) { return node, false }
			slice = append(slice[:tok.index], slice[tok.index+1:]...)
			return slice, true
		}
		mp, ok := node.(map[string]interface{})
		if !ok { return node, false }
		if _, exists := mp[tok.key]; !exists { return node, false }
		delete(mp, tok.key)
		return mp, true
	}
	if tok.isIndex {
		slice, ok := node.([]interface{})
		if !ok || tok.index < 0 || tok.index >= len(slice) { return node, false }
		child, ok := deleteAt(slice[tok.index], tokens[1:])
		if !ok { return node, false }
		slice[tok.index] = child
		return slice, true
	}
	mp, ok := node.(map[string]interface{})
	if !ok { return node, false }
	child, ok := deleteAt(mp[tok.key], tokens[1:])
	if !ok { return node, false }
	mp[tok.key] = child
	return mp, true
}
