```go
// Package fluentmap provides a fluent, chainable wrapper around
// map[string]interface{} values, making it convenient to access and
// manipulate arbitrary JSON-like data.
//
// A Map is a lightweight view over an existing map. Construct one with New,
// From, or Parse, then chain calls to read and mutate the underlying data:
//
//	m := fluentmap.New().
//		Set("name", "gopher").
//		SetPath("address.city", "Berlin")
//
//	city, _ := m.GetPathString("address.city") // "Berlin"
package fluentmap

import "sort"

// Map wraps a map[string]interface{} and exposes a fluent API. The zero value
// is not ready for use; construct instances with New, From, or Parse.
//
// A Map is not safe for concurrent use.
type Map struct {
	data map[string]interface{}
}

// New returns an empty Map. Any provided maps are wrapped (not copied) in
// order, so later maps overwrite earlier keys.
func New(maps ...map[string]interface{}) *Map {
	m := &Map{data: make(map[string]interface{})}
	for _, data := range maps {
		for k, v := range data {
			m.data[k] = v
		}
	}
	return m
}

// From wraps an existing map without copying it. Mutations to the returned Map
// are visible through data and vice versa.
func From(data map[string]interface{}) *Map {
	if data == nil {
		data = make(map[string]interface{})
	}
	return &Map{data: data}
}
```

