// Value returns the underlying map.
func (m *Map) Value() map[string]interface{} {
	if m == nil {
		return nil
	}
	return m.data
}

// Len reports the number of top-level entries.
func (m *Map) Len() int {
	if m == nil {
		return 0
	}
	return len(m.data)
}

// IsEmpty reports whether the map has no entries.
func (m *Map) IsEmpty() bool { return m.Len() == 0 }

// Keys returns the top-level keys in sorted order.
func (m *Map) Keys() []string {
	if m == nil {
		return nil
	}
	keys := make([]string, 0, len(m.data))
	for k := range m.data {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	return keys
}

// Has reports whether key exists at the top level.
func (m *Map) Has(key string) bool {
	if m == nil || m.data == nil {
		return false
	}
	_, ok := m.data[key]
	return ok
}

// Get returns the value for key at the top level.
func (m *Map) Get(key string) (interface{}, bool) {
	if m == nil || m.data == nil {
		return nil, false
	}
	v, ok := m.data[key]
	return v, ok
}

// MustGet returns the value for key or nil if it is absent.
func (m *Map) MustGet(key string) interface{} {
	v, _ := m.Get(key)
	return v
}

// Set assigns value to key and returns the receiver for chaining.
func (m *Map) Set(key string, value interface{}) *Map {
	if m.data == nil {
		m.data = make(map[string]interface{})
	}
	m.data[key] = value
	return m
}

// SetDefault assigns value to key only if key is not already present.
func (m *Map) SetDefault(key string, value interface{}) *Map {
	if !m.Has(key) {
		m.Set(key, value)
	}
	return m
}

// Delete removes the given top-level keys and returns the receiver.
func (m *Map) Delete(keys ...string) *Map {
	for _, k := range keys {
		delete(m.data, k)
	}
	return m
}

// Clear removes all entries and returns the receiver.
func (m *Map) Clear() *Map {
	for k := range m.data {
		delete(m.data, k)
	}
	return m
}
