// Clone returns a deep copy of the Map.
func (m *Map) Clone() *Map {
	if m == nil {
		return New()
	}
	return &Map{data: copyMap(m.data)}
}

// Each calls fn for every top-level entry in sorted key order. Returning false
// stops the iteration. Each returns the receiver for chaining.
func (m *Map) Each(fn func(key string, value interface{}) bool) *Map {
	for _, k := range m.Keys() {
		if !fn(k, m.data[k]) {
			break
		}
	}
	return m
}

// Filter returns a new Map containing only the entries for which fn returns true.
func (m *Map) Filter(fn func(key string, value interface{}) bool) *Map {
	out := New()
	if m == nil {
		return out
	}
	for _, k := range m.Keys() {
		if v := m.data[k]; fn(k, v) {
			out.data[k] = v
		}
	}
	return out
}

// Pick returns a new Map containing only the given top-level keys that exist.
func (m *Map) Pick(keys ...string) *Map {
	out := New()
	if m == nil {
		return out
	}
	for _, k := range keys {
		if v, ok := m.data[k]; ok {
			out.data[k] = v
		}
	}
	return out
}

// Omit returns a new Map without the given top-level keys.
func (m *Map) Omit(keys ...string) *Map {
	out := m.Clone()
	if out == nil {
		return New()
	}
	out.Delete(keys...)
	return out
}
